const LOGO="data:image/png;base64,";
const logoImg=new Image();logoImg.src=LOGO;
const SECTIONS=["الرابعة ابتدائي","الخامسة ابتدائي","الأولى متوسط","الثانية متوسط","الثالثة متوسط","الرابعة متوسط","الأولى ثانوي","قسم القرآن"];
const PLACE=["","الأول","الثاني","الثالث"];
let students=[];          // {id, section, name, hifz, tilawa, order}
let canWrite=true;
let loaded=false;
let view=(()=>{try{return localStorage.getItem("qc-view")||"dash"}catch(e){return "dash"}})();
const $=s=>document.querySelector(s);
const esc=s=>String(s??"").replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const isNum=v=>typeof v==="number"&&isFinite(v);

/* ---------- logic (mirrors the Excel formulas) ---------- */
function total(s){return isNum(s.hifz)&&isNum(s.tilawa)?s.hifz+s.tilawa:null}
function ranked(section){
  const list=students.filter(s=>s.section===section).sort((a,b)=>a.order-b.order);
  const scored=list.filter(s=>s.name&&total(s)!==null);
  // rank = count of higher totals + 1, ties broken by entry order (same as COUNTIF formula)
  return list.map(s=>{
    const t=total(s); if(t===null||!s.name) return {...s,total:t,rank:null};
    const higher=scored.filter(o=>total(o)>t).length;
    const earlierTie=scored.filter(o=>total(o)===t&&o.order<s.order).length;
    return {...s,total:t,rank:higher+earlierTie+1};
  });
}
function noteFor(r){return r==null?"":r<=3?PLACE[r]:"مشارك"}
function stats(section){
  const rows=ranked(section);
  const scored=rows.filter(r=>r.total!==null);
  return {count:rows.filter(r=>r.name).length,scored:scored.length,
    winners:rows.filter(r=>r.rank&&r.rank<=3).length,
    max:scored.length?Math.max(...scored.map(r=>r.total)):0,
    avg:scored.length?scored.reduce((a,r)=>a+r.total,0)/scored.length:null,
    top:[1,2,3].map(k=>rows.find(r=>r.rank===k)||null)};
}

/* ---------- rendering ---------- */
function renderTabs(){
  const t=$("#tabs");
  if(!me){t.hidden=true;t.innerHTML="";return}
  t.hidden=false;
  if(!isAdmin()){ // a teacher sees only the section assigned to them
    const i=SECTIONS.indexOf(me.section);
    if(i<0){t.innerHTML="";return}
    t.innerHTML=`<button class="main" data-v="s${i}" aria-selected="true">${esc(me.section)}</button>`;
    return;
  }
  t.innerHTML=`<button class="main" data-v="dash">لوحة المتابعة</button><button class="main" data-v="results">النتائج النهائية</button><button class="main" data-v="certs">الشهادات</button><button class="main" data-v="teachers">الأساتذة</button><button class="main" data-v="sections">الأقسام</button><button class="main" data-v="log">سجل التعديلات</button><span class="sep"></span>`+
    SECTIONS.map((s,i)=>`<button data-v="s${i}">${esc(s)}</button>`).join("");
  t.querySelectorAll("button").forEach(b=>{b.setAttribute("role","tab");b.setAttribute("aria-selected",b.dataset.v===view);b.onclick=()=>go(b.dataset.v)});
}
function go(v){view=v;try{localStorage.setItem("qc-view",v)}catch(e){}renderTabs();render();window.scrollTo({top:0})}

function render(){
  const el=$("#view");
  if(!me||view==="mycode"){return}
  if(!isAdmin()){
    const i=SECTIONS.indexOf(me.section);
    if(i<0){el.innerHTML=`<div class="empty">جارٍ تحميل القسم…</div>`;return}
    view="s"+i;
  }
  if(!loaded){el.innerHTML=`<div class="empty">جارٍ تحميل قوائم التلاميذ…</div>`;return}
  if(view==="teachers"){el.innerHTML=teachersHTML();bindTeachers(el);return}
  if(view==="log"){el.innerHTML=logHTML();return}
  if(view==="sections"){el.innerHTML=sectionsAdminHTML();bindSectionsAdmin(el);return}
  if(view==="dash") el.innerHTML=dashHTML();
  else if(view==="results") el.innerHTML=resultsHTML();
  else if(view==="certs"){el.innerHTML=certsHTML();bindCerts()}
  else {const i=+view.slice(1); if(!SECTIONS[i]){view="dash";return render()} el.innerHTML=sectionHTML(i); bindSection(i)}
  el.querySelectorAll("[data-go]").forEach(r=>r.onclick=()=>go(r.dataset.go));
  el.querySelectorAll("[data-cert]").forEach(b=>b.onclick=()=>{certSec=+b.dataset.cert;certFilter="win";certSel=null;go("certs")});
  const ex=el.querySelector("#export"); if(ex) ex.onclick=exportCSV;
  if(typeof bindData==="function") bindData(el);
}

function dashHTML(){
  const all=SECTIONS.map(stats);
  const sum=k=>all.reduce((a,s)=>a+s[k],0);
  const best=Math.max(0,...all.map(s=>s.max));
  return `<div style="display:grid;gap:16px">
  <div><h2>لوحة مسؤول النشاط</h2><p class="sub">إحصائيات المشاركين والنتائج حسب الأقسام. اضغط على قسم لفتحه.</p></div>
  ${isAdmin()?progressHTML()+dataPanelHTML():""}
  <div class="kpis">
    <div class="kpi"><b>${sum("count")}</b><span>مجموع المشاركين</span></div>
    <div class="kpi"><b>${sum("scored")}</b><span>تلاميذ لديهم علامات كاملة</span></div>
    <div class="kpi"><b>${sum("count")-sum("scored")}</b><span>بانتظار التنقيط</span></div>
    <div class="kpi"><b>${best}<small style="font-size:.9rem;color:var(--muted)"> /20</small></b><span>أعلى علامة في المسابقة</span></div>
  </div>
  <div class="tbl"><table>
    <thead><tr><th>القسم</th><th class="num">المشاركون</th><th class="num">أصحاب النقاط</th><th class="num">الفائزون</th><th>أعلى علامة /20</th><th class="num">المعدل</th><th>الأول</th></tr></thead>
    <tbody>${all.map((s,i)=>`<tr class="clickable" data-go="s${i}" tabindex="0">
      <td><strong>${esc(SECTIONS[i])}</strong></td><td class="num">${s.count}</td><td class="num">${s.scored}</td><td class="num">${s.winners}</td>
      <td>${s.max}<span class="bar" style="width:${s.max*4}px"></span></td>
      <td class="num">${s.avg==null?"–":s.avg.toFixed(1)}</td>
      <td>${s.top[0]?esc(s.top[0].name):'<span class="pend">—</span>'}</td></tr>`).join("")}</tbody>
  </table></div>
  <p class="note">طريقة الاستخدام: افتح القسم، أدخل اسم التلميذ وعلامتي الحفظ والتلاوة. المجموع والترتيب والملاحظة والنتائج النهائية والإحصائيات تُحدّث تلقائياً.</p>
  </div>`;
}

function sectionHTML(i){
  const sec=SECTIONS[i], rows=ranked(sec), st=stats(sec);
  const dis=canWrite?"":"disabled";
  const podium=[1,2,3].map(k=>{const r=st.top[k-1];return `<div><small class="p${k}">${["🥇","🥈","🥉"][k-1]} ${PLACE[k]}</small><strong>${r?esc(r.name):"—"}</strong><em>${r?r.total+" /20":"لم يُحدد بعد"}</em></div>`}).join("");
  return `<div style="display:grid;gap:14px">
  <div class="row-actions"><div><h2>${esc(sec)}</h2><p class="sub">${st.count} مشارك · ${st.scored} بعلامات كاملة · أعلى علامة ${st.max}/20</p></div></div>
  <div class="podium">${podium}</div>
  <div class="tbl"><table>
    <thead><tr><th class="num">#</th><th>اسم التلميذ</th><th class="num">الحفظ /10</th><th class="num">التلاوة والتجويد /10</th><th class="num">المجموع /20</th><th class="num">الترتيب</th><th>ملاحظة</th><th></th></tr></thead>
    <tbody>${rows.length?rows.map((r,n)=>`<tr data-id="${r.id}">
      <td class="num pend">${n+1}</td>
      <td><input class="name" id="n-${r.id}" data-f="name" value="${esc(r.name)}" ${dis} aria-label="اسم التلميذ"></td>
      <td class="num"><input class="mark" id="h-${r.id}" data-f="hifz" type="number" min="0" max="10" step="0.25" inputmode="decimal" value="${isNum(r.hifz)?r.hifz:""}" ${dis} aria-label="الحفظ"></td>
      <td class="num"><input class="mark" id="t-${r.id}" data-f="tilawa" type="number" min="0" max="10" step="0.25" inputmode="decimal" value="${isNum(r.tilawa)?r.tilawa:""}" ${dis} aria-label="التلاوة والتجويد"></td>
      <td class="num"><strong>${r.total??'<span class="pend">—</span>'}</strong></td>
      <td class="num">${r.rank??'<span class="pend">—</span>'}</td>
      <td>${r.rank?`<span class="pill p${r.rank<=3?r.rank:0}">${noteFor(r.rank)}</span>`:'<span class="pend">بانتظار العلامات</span>'}</td>
      <td>${isAdmin()?`<button class="del" data-del="${r.id}" title="حذف التلميذ" aria-label="حذف">✕</button>`:""}</td>
    </tr>`).join(""):`<tr><td colspan="8" class="empty">لا يوجد تلاميذ في هذا القسم بعد. أضف أول تلميذ من النموذج أدناه.</td></tr>`}</tbody>
  </table></div>
  ${canWrite?`<form class="add" id="addForm">
    <label class="grow">اسم التلميذ<input id="addName" required autocomplete="off" placeholder="الاسم واللقب"></label>
    <label>الحفظ /10<input id="addH" type="number" min="0" max="10" step="0.25" inputmode="decimal"></label>
    <label>التلاوة /10<input id="addT" type="number" min="0" max="10" step="0.25" inputmode="decimal"></label>
    <button class="btn" type="submit">إضافة تلميذ</button>
  </form>`:""}
  </div>`;
}

function parseMark(v){if(v===""||v==null)return null;const n=Number(v);return isFinite(n)&&n>=0&&n<=10?n:undefined}

function bindSection(i){
  const el=$("#view");
  el.querySelectorAll("input[data-f]").forEach(inp=>{
    inp.addEventListener("change",()=>{
      const id=inp.closest("tr").dataset.id,f=inp.dataset.f;
      let val;
      if(f==="name"){val=inp.value.trim(); if(!val){inp.value=students.find(s=>s.id===id)?.name||"";return}}
      else{val=parseMark(inp.value); if(val===undefined){inp.classList.add("bad");setStatus("العلامة يجب أن تكون بين 0 و 10",true);return} inp.classList.remove("bad")}
      saveField(id,{[f]:val});
    });
  });
  el.querySelectorAll("[data-del]").forEach(b=>b.onclick=()=>{
    if(!b.classList.contains("confirm")){b.classList.add("confirm");b.textContent="تأكيد الحذف";setTimeout(()=>{if(b.isConnected){b.classList.remove("confirm");b.textContent="✕"}},4000);return}
    removeStudent(b.dataset.del);
  });
  const f=$("#addForm");
  if(f) f.onsubmit=e=>{
    e.preventDefault();
    const name=$("#addName").value.trim(); if(!name) return;
    const h=parseMark($("#addH").value), t=parseMark($("#addT").value);
    if(h===undefined||t===undefined){setStatus("العلامة يجب أن تكون بين 0 و 10",true);return}
    addStudent({section:SECTIONS[i],name,hifz:h,tilawa:t,order:Date.now()});
    f.reset(); $("#addName").focus();
  };
}

function resultsHTML(){
  return `<div style="display:grid;gap:16px">
  <div class="row-actions"><div><h2>النتائج النهائية</h2><p class="sub">الفائزون الثلاثة الأوائل في كل قسم</p></div>
  <button class="btn ghost" id="export" ${dl?"":"hidden"}>تنزيل النتائج (CSV)</button></div>
  <div class="honour">${SECTIONS.map((sec,i)=>{const st=stats(sec);return `<div class="card">
    <h3>${esc(sec)}</h3>
    <ol>${[1,2,3].map(k=>{const r=st.top[k-1];return `<li><span class="pill p${k}">${PLACE[k]}</span><span class="n">${r?esc(r.name):'<span class="pend">—</span>'}</span><span class="s">${r?`${r.hifz} + ${r.tilawa} = <strong>${r.total}</strong>`:""}</span></li>`}).join("")}</ol>
    <div class="actions"><button class="btn ghost" data-go="s${i}" style="padding:4px 12px;font-size:.85rem">فتح القسم</button><button class="btn ghost" data-cert="${i}" style="padding:4px 12px;font-size:.85rem">الشهادات</button></div>
  </div>`}).join("")}</div></div>`;
}

/* ---------- certificates ---------- */
let certSettings={org:"",signerTitle:"مسؤول النشاط",signer:"",date:""};
let certSec=0, certFilter="win", certSel=null;
const PLACE_F=["","الأولى","الثانية","الثالثة"];
const MEDAL=["#3d6b62","#b8892a","#7d878c","#a3653c"];
function todayAr(){try{return new Intl.DateTimeFormat("ar-DZ",{day:"numeric",month:"long",year:"numeric"}).format(new Date())}catch(e){return new Date().toLocaleDateString()}}
function certList(){const rows=ranked(SECTIONS[certSec]).filter(r=>r.name);
  return (certFilter==="win"?rows.filter(r=>r.rank&&r.rank<=3):rows).sort((a,b)=>(a.rank??999)-(b.rank??999)||a.order-b.order)}

function certsHTML(){
  const list=certList();
  if(!list.find(r=>r.id===certSel)) certSel=list[0]?.id||null;
  const cs=certSettings;
  return `<div style="display:grid;gap:14px">
  <div><h2>شهادات التقدير</h2><p class="sub">شهادة تقدير للثلاثة الأوائل وشهادة مشاركة لباقي التلاميذ، تُملأ تلقائياً من النتائج.</p></div>
  <div class="certs">
    <div style="display:grid;gap:14px;min-width:0">
      <div class="panel"><h3>بيانات الشهادة</h3>
        <label class="field">اسم المؤسسة أو المدرسة<input id="cOrg" data-c="org" value="${esc(cs.org)}" placeholder="يظهر إذا لم يتوفر الشعار" ${canWrite?"":"disabled"}></label>
        <label class="field">صفة الموقِّع<input id="cTitle" data-c="signerTitle" value="${esc(cs.signerTitle)}" ${canWrite?"":"disabled"}></label>
        <label class="field">اسم الموقِّع<input id="cSigner" data-c="signer" value="${esc(cs.signer)}" placeholder="الاسم الذي يظهر أسفل الشهادة" ${canWrite?"":"disabled"}></label>
        <label class="field">التاريخ<input id="cDate" data-c="date" value="${esc(cs.date)}" placeholder="${esc(todayAr())}" ${canWrite?"":"disabled"}></label>
      </div>
      <div class="panel"><h3>التلاميذ</h3>
        <label class="field">القسم<select id="cSec">${SECTIONS.map((s,i)=>`<option value="${i}" ${i===certSec?"selected":""}>${esc(s)}</option>`).join("")}</select></label>
        <div class="seg"><button data-flt="win" aria-pressed="${certFilter==="win"}">الفائزون</button><button data-flt="all" aria-pressed="${certFilter==="all"}">جميع المشاركين</button></div>
        <div class="clist">${list.length?list.map(r=>`<button class="item" data-sel="${r.id}" aria-current="${r.id===certSel}"><span>${esc(r.name)}</span>${r.rank&&r.rank<=3?`<span class="pill p${r.rank}">${PLACE[r.rank]}</span>`:'<span class="pill p0">مشاركة</span>'}</button>`).join(""):`<div class="empty">لا يوجد ${certFilter==="win"?"فائزون":"تلاميذ"} في هذا القسم بعد.</div>`}</div>
      </div>
    </div>
    <div class="panel preview">
      <div class="row-actions"><h3>معاينة الشهادة</h3>
        <div class="actions" ${dl?"":"hidden"}>
          <button class="btn" id="dlOne" ${certSel?"":"disabled"}>تنزيل هذه الشهادة (PNG)</button>
          <button class="btn ghost" id="dlSec" ${list.length?"":"disabled"}>شهادات القائمة (PDF)</button>
          <button class="btn ghost" id="dlAll">كل الفائزين في الأقسام (PDF)</button>
        </div></div>
      ${certSel?`<canvas id="certCanvas" width="1754" height="1240" aria-label="معاينة الشهادة"></canvas>`:`<div class="empty">اختر تلميذاً لمعاينة شهادته.</div>`}
      ${dl?"":`<p class="note">التنزيل غير متاح في هذا العرض. افتح الصفحة على claude.ai لتنزيل الشهادات.</p>`}
    </div>
  </div></div>`;
}

function bindCerts(){
  const el=$("#view");
  el.querySelectorAll("[data-c]").forEach(inp=>inp.addEventListener("change",()=>saveSettings({[inp.dataset.c]:inp.value.trim()})));
  el.querySelectorAll("[data-c]").forEach(inp=>inp.addEventListener("input",()=>{certSettings[inp.dataset.c]=inp.value.trim();drawPreview()}));
  $("#cSec").onchange=e=>{certSec=+e.target.value;certSel=null;render()};
  el.querySelectorAll("[data-flt]").forEach(b=>b.onclick=()=>{certFilter=b.dataset.flt;certSel=null;render()});
  el.querySelectorAll("[data-sel]").forEach(b=>b.onclick=()=>{certSel=b.dataset.sel;render()});
  const one=$("#dlOne"); if(one) one.onclick=downloadOne;
  const sec=$("#dlSec"); if(sec) sec.onclick=()=>downloadPDF(certList().map(r=>[r,SECTIONS[certSec]]),`شهادات-${SECTIONS[certSec]}.pdf`);
  const all=$("#dlAll"); if(all) all.onclick=()=>{const items=[];SECTIONS.forEach(s=>ranked(s).filter(r=>r.rank&&r.rank<=3).sort((a,b)=>a.rank-b.rank).forEach(r=>items.push([r,s])));downloadPDF(items,"شهادات-الفائزين.pdf")};
  drawPreview();
}

let fontsReady=null;
function ensureFonts(){return fontsReady||(fontsReady=Promise.all([logoImg.decode().catch(()=>{}),'700 80px "Amiri"','400 40px "Amiri"','600 34px "IBM Plex Sans Arabic"','400 34px "IBM Plex Sans Arabic"'].map(f=>document.fonts.load(f,"شهادة"))).catch(()=>{}))}
async function drawPreview(){
  const c=document.getElementById("certCanvas"); if(!c) return;
  const r=certList().find(x=>x.id===certSel); if(!r) return;
  await ensureFonts(); drawCert(c.getContext("2d"),r,SECTIONS[certSec]);
}

function star(ctx,x,y,R,fill){ // eight-pointed star (two overlapping squares)
  ctx.save();ctx.translate(x,y);ctx.fillStyle=fill;
  for(const a of [0,Math.PI/4]){ctx.save();ctx.rotate(a);ctx.fillRect(-R/2,-R/2,R,R);ctx.restore()}
  ctx.fillStyle="#fffdf6";ctx.beginPath();ctx.arc(0,0,R*.22,0,Math.PI*2);ctx.fill();ctx.restore();
}
function fitText(ctx,txt,x,y,maxW,font,size){let s=size;do{ctx.font=font.replace("{s}",s)}while(ctx.measureText(txt).width>maxW&&(s-=2)>14);ctx.fillText(txt,x,y)}

function drawCert(ctx,r,sec){
  const W=1754,H=1240,cx=W/2,green="#0f5c4d",gold="#b8892a",ink="#1d2b27",muted="#5e6b66";
  const winner=r.rank&&r.rank<=3, cs=certSettings;
  ctx.setTransform(1,0,0,1,0,0);ctx.direction="rtl";ctx.textAlign="center";ctx.textBaseline="alphabetic";
  ctx.fillStyle="#fffdf6";ctx.fillRect(0,0,W,H);
  // frame
  ctx.strokeStyle=green;ctx.lineWidth=10;ctx.strokeRect(38,38,W-76,H-76);
  ctx.strokeStyle=gold;ctx.lineWidth=3;ctx.strokeRect(62,62,W-124,H-124);
  ctx.lineWidth=1.5;ctx.strokeRect(74,74,W-148,H-148);
  [[62,62],[W-62,62],[62,H-62],[W-62,H-62]].forEach(([x,y])=>star(ctx,x,y,56,gold));
  for(let i=0;i<9;i++){const x=cx+(i-4)*190; if(i!==4){star(ctx,x,62,18,green);star(ctx,x,H-62,18,green)}}
  // header
  // the school logo already carries the school's name, so it replaces the name line
  const lg=logoImg.complete&&logoImg.naturalWidth?logoImg:null;
  if(lg){const h=150,w=h*lg.naturalWidth/lg.naturalHeight;ctx.imageSmoothingQuality="high";ctx.drawImage(lg,cx-w/2,92,w,h);
    ctx.fillStyle=muted;ctx.font='400 30px "IBM Plex Sans Arabic", sans-serif';ctx.fillText("مسابقة القرآن الكريم السنوية",cx,285)}
  else{ctx.fillStyle=ink;fitText(ctx,cs.org||"مسابقة القرآن الكريم السنوية",cx,175,1300,'600 {s}px "IBM Plex Sans Arabic", sans-serif',38);
    if(cs.org){ctx.fillStyle=muted;ctx.font='400 30px "IBM Plex Sans Arabic", sans-serif';ctx.fillText("مسابقة القرآن الكريم السنوية",cx,225)}}
  const dv=lg?445:425;
  ctx.fillStyle=green;ctx.font=`700 ${lg?112:128}px "Amiri", serif`;ctx.fillText(winner?"شهادة تقدير":"شهادة مشاركة",cx,lg?400:380);
  ctx.strokeStyle=gold;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(cx-260,dv);ctx.lineTo(cx-40,dv);ctx.moveTo(cx+40,dv);ctx.lineTo(cx+260,dv);ctx.stroke();star(ctx,cx,dv,26,gold);
  ctx.fillStyle=ink;ctx.font='400 40px "IBM Plex Sans Arabic", sans-serif';ctx.fillText("يسرّنا أن نمنح هذه الشهادة للتلميذ",cx,515);
  ctx.fillStyle=winner?MEDAL[r.rank]:green;fitText(ctx,r.name,cx,640,1350,'700 {s}px "Amiri", serif',100);
  ctx.fillStyle=ink;
  fitText(ctx,winner?`تقديراً لحصوله على المرتبة ${PLACE_F[r.rank]} في مسابقة القرآن الكريم السنوية – ${sec}`:`تقديراً لمشاركته المتميزة في مسابقة القرآن الكريم السنوية – ${sec}`,cx,745,1450,'400 {s}px "IBM Plex Sans Arabic", sans-serif',42);
  if(r.total!=null){ctx.fillStyle=muted;ctx.font='400 32px "IBM Plex Sans Arabic", sans-serif';ctx.fillText(`بمجموع ${r.total} من 20  ·  الحفظ ${r.hifz}/10  ·  التلاوة والتجويد ${r.tilawa}/10`,cx,810)}
  ctx.fillStyle=gold;ctx.font='400 44px "Amiri", serif';ctx.fillText("«خيرُكم من تعلَّم القرآنَ وعلَّمه»",cx,885);
  ctx.fillStyle=muted;ctx.font='400 26px "IBM Plex Sans Arabic", sans-serif';ctx.fillText("حديث شريف",cx,925);
  // seal
  if(winner){const sy=1065,c=MEDAL[r.rank];
    ctx.fillStyle=c;for(let i=0;i<24;i++){ctx.save();ctx.translate(cx,sy);ctx.rotate(i*Math.PI/12);ctx.beginPath();ctx.moveTo(-14,-78);ctx.lineTo(0,-96);ctx.lineTo(14,-78);ctx.fill();ctx.restore()}
    ctx.beginPath();ctx.arc(cx,sy,80,0,Math.PI*2);ctx.fill();
    ctx.strokeStyle="#fffdf6";ctx.lineWidth=3;ctx.beginPath();ctx.arc(cx,sy,66,0,Math.PI*2);ctx.stroke();
    ctx.fillStyle="#fffdf6";ctx.font='700 46px "Amiri", serif';ctx.fillText(PLACE[r.rank],cx,sy+16);}
  // signatures
  ctx.fillStyle=ink;ctx.font='600 32px "IBM Plex Sans Arabic", sans-serif';
  ctx.fillText(cs.signerTitle||"مسؤول النشاط",W-360,1015);ctx.fillText("التاريخ",360,1015);
  ctx.strokeStyle=muted;ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(W-520,1100);ctx.lineTo(W-200,1100);ctx.moveTo(200,1100);ctx.lineTo(520,1100);ctx.stroke();
  ctx.fillStyle=muted;ctx.font='400 30px "IBM Plex Sans Arabic", sans-serif';
  if(cs.signer) ctx.fillText(cs.signer,W-360,1145);
  ctx.fillText(cs.date||todayAr(),360,1080);
}

async function renderToCanvas(r,sec){await ensureFonts();const c=document.createElement("canvas");c.width=1754;c.height=1240;drawCert(c.getContext("2d"),r,sec);return c}
async function downloadOne(){
  const r=certList().find(x=>x.id===certSel); if(!r||!dl) return;
  const c=await renderToCanvas(r,SECTIONS[certSec]);
  const blob=await new Promise(res=>c.toBlob(res,"image/png"));
  try{await dl.save({filename:`شهادة-${r.name}.png`,data:blob});setStatus("تم تنزيل الشهادة")}catch(e){setStatus(e.code==="declined"?"أُلغي التنزيل":"تعذر التنزيل",e.code!=="declined")}
}
async function downloadPDF(items,filename){
  if(!dl||!items.length){setStatus("لا توجد شهادات للتنزيل",true);return}
  if(!window.jspdf){setStatus("تعذر تحميل مكتبة PDF، جرّب تنزيل الشهادات كصور",true);return}
  setStatus(`جارٍ تجهيز ${items.length} شهادة…`);
  const pdf=new window.jspdf.jsPDF({orientation:"landscape",unit:"mm",format:"a4"});
  for(let i=0;i<items.length;i++){const c=await renderToCanvas(...items[i]);if(i)pdf.addPage();pdf.addImage(c.toDataURL("image/jpeg",.92),"JPEG",0,0,297,210)}
  try{await dl.save({filename,data:pdf.output("blob")});setStatus("تم تنزيل ملف الشهادات")}catch(e){setStatus(e.code==="declined"?"أُلغي التنزيل":"تعذر التنزيل",e.code!=="declined")}
}
let settingsDoc=null;
async function saveSettings(patch){
  Object.assign(certSettings,patch);
  if(settingsDoc){try{await settingsDoc.set({...certSettings});setStatus("تم حفظ بيانات الشهادة")}catch(e){setStatus("تعذر الحفظ: "+(e.message||e.code),true)}}
  else{try{localStorage.setItem("qc-cert",JSON.stringify(certSettings))}catch(e){}}
  drawPreview();
}

/* ---------- export ---------- */
let dl=null;
async function exportCSV(){
  const lines=[["القسم","اسم التلميذ","الحفظ /10","التلاوة والتجويد /10","المجموع /20","الترتيب","ملاحظة"]];
  SECTIONS.forEach(sec=>ranked(sec).sort((a,b)=>(a.rank??999)-(b.rank??999)).forEach(r=>lines.push([sec,r.name,r.hifz??"",r.tilawa??"",r.total??"",r.rank??"",noteFor(r.rank)])));
  const csv="﻿"+lines.map(l=>l.map(c=>`"${String(c).replace(/"/g,'""')}"`).join(",")).join("\r\n");
  try{await dl.save({filename:"نتائج-مسابقة-القرآن.csv",data:new Blob([csv],{type:"text/csv"})});setStatus("تم تنزيل الملف")}
  catch(e){setStatus("لم يتم التنزيل",true)}
}

